// Public issue text is data only. Never execute commands or follow links from comments.
internal static class IssueRepair
{
    private static readonly object Gate = new object();
    private const string Repo = "https://api.github.com/repos/V3nilla/IPSets-For-Bypass-in-Russia/";
    private static string Data { get { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "ZapretSimpleGui"); } }
    internal static bool Enabled { get { return File.Exists(Path.Combine(Data, "issue-repair.enabled")); } }
    internal static void Enable(bool value)
    {
        Directory.CreateDirectory(Data);
        string p = Path.Combine(Data, "issue-repair.enabled");
        if (value) File.WriteAllText(p, "enabled"); else if (File.Exists(p)) File.Delete(p);
    }
    internal static string LastLog { get { string p = Path.Combine(Data, "issue-repair.log"); return File.Exists(p) ? File.ReadAllText(p) : "Проверок ещё не было."; } }
    private static string Get(Dictionary<string, object> item, string key)
    { object value; return item.TryGetValue(key, out value) && value != null ? Convert.ToString(value) : ""; }
    private static IEnumerable<Dictionary<string, object>> Json(string path)
    {
        string json = Encoding.UTF8.GetString(NetworkFiles.Download(Repo + path, 2 * 1024 * 1024));
        // Framework assembly loaded by name to keep compatibility with the original installer compiler arguments.
        Type type = Type.GetType("System.Web.Script.Serialization.JavaScriptSerializer, System.Web.Extensions, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35", true);
        object reader = Activator.CreateInstance(type);
        type.GetProperty("MaxJsonLength").SetValue(reader, 2 * 1024 * 1024, null);
        object[] items = type.GetMethod("DeserializeObject").Invoke(reader, new object[] { json }) as object[];
        if (items == null) throw new InvalidDataException("GitHub вернул неожиданный формат.");
        return items.OfType<Dictionary<string, object>>();
    }
    private sealed class Candidate { internal string Ip, Source; }
    private static void Collect(string body, string source, List<Candidate> result)
    {
        foreach (Match match in Regex.Matches(body, @"(?<![\d.])(?:\d{1,3}\.){3}\d{1,3}(?![\d.])"))
        {
            try {
                string ip = ListUpdates.ValidateAddress(match.Value);
                byte[] b = IPAddress.Parse(ip).GetAddressBytes();
                if (!PublicAddress(ip)) continue;
                if (!result.Any(c => c.Ip == ip)) result.Add(new Candidate { Ip = ip, Source = source });
            } catch (InvalidDataException) { }
        }
    }
    private static bool PublicAddress(string value)
    {
        try {
            byte[] b = IPAddress.Parse(ListUpdates.ValidateAddress(value)).GetAddressBytes();
            return !(b[0] == 192 && (b[1] == 0 || b[1] == 168 || (b[1] == 88 && b[2] == 99))) &&
                !(b[0] == 198 && (b[1] == 18 || b[1] == 19 || (b[1] == 51 && b[2] == 100))) &&
                !(b[0] == 203 && b[1] == 0 && b[2] == 113);
        } catch { return false; }
    }
    private static List<Candidate> Find(string domain, string current, IEnumerable<Dictionary<string, object>> issues,
        Dictionary<string, List<Dictionary<string, object>>> cache)
    {
        List<Candidate> found = new List<Candidate>();
        string[] labels = domain.Split('.');
        string service = labels.Length > 1 ? labels[labels.Length - 2] : domain;
        foreach (var issue in issues)
        {
            if (issue.ContainsKey("pull_request")) continue;
            string body = Get(issue, "body"), context = Get(issue, "title") + " " + body;
            bool relevant = context.IndexOf(domain, StringComparison.OrdinalIgnoreCase) >= 0 ||
                context.IndexOf(current, StringComparison.Ordinal) >= 0 ||
                (service.Length >= 4 && Regex.IsMatch(context, @"(?<![a-z0-9])" + Regex.Escape(service) + @"(?![a-z0-9])", RegexOptions.IgnoreCase));
            if (!relevant) continue;
            string number = Get(issue, "number");
            if (!Regex.IsMatch(number, @"^\d+$")) continue;
            string source = "https://github.com/V3nilla/IPSets-For-Bypass-in-Russia/issues/" + number;
            List<Dictionary<string, object>> comments;
            if (!cache.TryGetValue(number, out comments))
            {
                if (cache.Count >= 6) { Collect(body, source, found); continue; }
                comments = Json("issues/" + number + "/comments?per_page=100").ToList(); cache[number] = comments;
            }
            foreach (var comment in comments.AsEnumerable().Reverse())
                Collect(Get(comment, "body"), source + "#issuecomment-" + Get(comment, "id"), found);
            Collect(body, source, found);
        }
        return found.Where(c => PublicAddress(c.Ip)).Take(12).ToList();
    }
    // 0: transport failed; HTTP codes remain distinct, including Cloudflare 403.
    private static int Probe(string domain, string ip)
    {
        string curl = Path.Combine(Environment.SystemDirectory, "curl.exe");
        if (!File.Exists(curl)) throw new IOException("Нужен системный curl.exe Windows для проверки HTTPS. Hosts не изменён.");
        string args = "-q --noproxy \"*\" --proto =https --connect-timeout 5 --max-time 10 --silent --output NUL --head --write-out %{http_code}";
        if (ip != null) args += " --resolve \"" + domain + ":443:" + ip + "\"";
        args += " https://" + domain + "/";
        using (Process p = new Process { StartInfo = new ProcessStartInfo(curl, args) { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true } })
        {
            p.Start();
            if (!p.WaitForExit(12000)) { try { p.Kill(); } catch { } return 0; }
            int status; return p.ExitCode == 0 && int.TryParse(p.StandardOutput.ReadToEnd().Trim(), out status) ? status : 0;
        }
    }
    // Parse every alias, including blocked aliases: a conflicting 0.0.0.0 entry must never be unblocked.
    internal static Dictionary<string, string> Eligible(string text)
    {
        var addresses = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        foreach (string line in text.Split('\n'))
        {
            string[] fields = Regex.Split(line.Split('#')[0].Trim(), @"\s+");
            if (fields.Length < 2) continue;
            foreach (string raw in fields.Skip(1))
            {
                string domain = raw.TrimEnd('.').ToLowerInvariant();
                if (domain.Length > 253 || !Regex.IsMatch(domain, @"^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9-]{2,63}$")) continue;
                HashSet<string> set;
                if (!addresses.TryGetValue(domain, out set)) addresses[domain] = set = new HashSet<string>();
                set.Add(fields[0]);
            }
        }
        return addresses.Where(pair => pair.Value.Count == 1 && PublicAddress(pair.Value.First()))
            .ToDictionary(pair => pair.Key, pair => pair.Value.First(), StringComparer.OrdinalIgnoreCase);
    }
    internal static string Merge(string text, Dictionary<string, string> eligible, Dictionary<string, string> replacements)
    {
        StringBuilder output = new StringBuilder();
        foreach (string raw in Regex.Split(text, @"(?<=\n)"))
        {
            string body = raw.Split('#')[0].Trim();
            string[] fields = Regex.Split(body, @"\s+");
            if (fields.Length < 2 || !PublicAddress(fields[0])) { output.Append(raw); continue; }
            var changed = fields.Skip(1).Where(d => replacements.ContainsKey(d.TrimEnd('.').ToLowerInvariant()) &&
                eligible.ContainsKey(d.TrimEnd('.').ToLowerInvariant()) && eligible[d.TrimEnd('.').ToLowerInvariant()] == fields[0]).ToArray();
            if (changed.Length == 0) { output.Append(raw); continue; }
            string comment = raw.Contains("#") ? " " + raw.Substring(raw.IndexOf('#')).TrimEnd('\r', '\n') : "";
            var keep = fields.Skip(1).Except(changed).ToArray();
            if (keep.Length > 0) { output.Append(fields[0]).Append(' ').Append(string.Join(" ", keep)).Append(comment).Append("\r\n"); comment = ""; }
            foreach (string domain in changed)
            { output.Append(replacements[domain.TrimEnd('.').ToLowerInvariant()]).Append(' ').Append(domain).Append(comment).Append("\r\n"); comment = ""; }
        }
        return output.ToString();
    }
    internal static string Run(bool automatic = false)
    {
        if (!System.Threading.Monitor.TryEnter(Gate)) return "Проверка issues уже выполняется.";
        StringBuilder log = new StringBuilder(DateTime.Now.ToString("s") + "\r\n");
        Stopwatch elapsed = Stopwatch.StartNew();
        try
        {
            string hosts = Path.Combine(Environment.SystemDirectory, "drivers", "etc", "hosts");
            string expected = HostsWriter.ReadHash(hosts);
            string text = Files.Text(File.ReadAllBytes(hosts));
            var eligible = Eligible(text);
            string[] domains = eligible.Keys.OrderBy(d => d, StringComparer.Ordinal).ToArray();
            log.AppendLine("Доменов с единственным публичным IPv4: " + domains.Length + ". 0.0.0.0, локальные/служебные адреса, IPv6 и конфликтующие записи исключены.");
            if (domains.Length == 0) return log.ToString();
            Directory.CreateDirectory(Data);
            string cursorFile = Path.Combine(Data, "issue-repair.cursor");
            int cursor = 0;
            if (File.Exists(cursorFile)) int.TryParse(File.ReadAllText(cursorFile), out cursor);
            cursor = Math.Max(0, cursor) % domains.Length;
            var replacements = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            List<Dictionary<string, object>> issues = null;
            var cache = new Dictionary<string, List<Dictionary<string, object>>>();
            int checkedCount = 0;
            for (int i = 0; i < Math.Min(25, domains.Length); i++)
            {
                if (elapsed.Elapsed.TotalSeconds > 180 || (automatic && !Enabled)) break;
                string domain = domains[(cursor + i) % domains.Length], current = eligible[domain];
                int status = Probe(domain, current); checkedCount++;
                log.AppendLine(domain + " / " + current + ": HTTP " + status);
                if (status > 0 && status < 500) continue;
                int retry = Probe(domain, current);
                if (retry > 0 && retry < 500) continue;
                if (issues == null) issues = Json("issues?state=all&sort=updated&direction=desc&per_page=30").ToList();
                foreach (Candidate candidate in Find(domain, current, issues, cache).Where(c => c.Ip != current))
                {
                    if (elapsed.Elapsed.TotalSeconds > 180) break;
                    int code = Probe(domain, candidate.Ip);
                    log.AppendLine("Кандидат " + candidate.Ip + ": HTTP " + code + " — " + candidate.Source);
                    if (code < 200 || code >= 400) continue;
                    code = Probe(domain, candidate.Ip);
                    if (code < 200 || code >= 400) continue;
                    replacements[domain] = candidate.Ip; break;
                }
            }
            File.WriteAllText(cursorFile, ((cursor + checkedCount) % domains.Length).ToString());
            log.AppendLine("Проверено " + checkedCount + " из " + domains.Length + ". Следующая проверка продолжит обход. За запуск: до 25 доменов, около 3 минут плюс текущий запрос.");
            if (replacements.Count == 0) { log.AppendLine("Подтверждённых замен нет. Hosts не изменён."); return log.ToString(); }
            if (automatic && !Enabled) { log.AppendLine("Автопроверка отключена; запись отменена."); return log.ToString(); }
            byte[] applied = new UTF8Encoding(false).GetBytes(Merge(text, eligible, replacements));
            Files.ValidateHosts(applied);
            string backup = HostsWriter.Replace(hosts, applied, expected);
            log.AppendLine("Заменено доменов: " + replacements.Count + ". Резервная копия: " + backup);
            foreach (var pair in replacements) log.AppendLine(pair.Key + ": " + eligible[pair.Key] + " -> " + pair.Value);
            try { HostsGuard.Remember(applied); }
            catch (Exception e) { log.AppendLine("Hosts заменён; сохранить контрольную копию не удалось: " + e.Message); }
            // Do not save one generic GeoHide IP: different services can now use different addresses.
            using (Process p = Process.Start(new ProcessStartInfo(Path.Combine(Environment.SystemDirectory, "ipconfig.exe"), "/flushdns") { UseShellExecute = false, CreateNoWindow = true })) p.WaitForExit(5000);
            log.AppendLine("Перезапусти браузер и проверь нужные функции сайтов. Полное обновление hosts может перезаписать эти точечные исправления.");
            return log.ToString();
        }
        catch (Exception e) { log.AppendLine("Проверка остановлена: " + e.Message); return log.ToString(); }
        finally
        {
            try { Directory.CreateDirectory(Data); File.WriteAllText(Path.Combine(Data, "issue-repair.log"), log.ToString()); } catch { }
            System.Threading.Monitor.Exit(Gate);
        }
    }
    internal static void StartAutomatic()
    {
        if (!Enabled) return;
        System.Threading.ThreadPool.QueueUserWorkItem(delegate { Run(true); });
    }
    internal static string MetaDomains(string folder)
    {
        string path = Path.Combine(folder, "lists", "list-general-user.txt");
        string original = File.Exists(path) ? Files.Text(File.ReadAllBytes(path)) : "";
        string[] domains = { "meta.com", "metacdn.com", "facebook.com", "facebook.net", "fbcdn.net", "oculus.com", "oculuscdn.com" };
        var existing = new HashSet<string>(original.Split('\n').Select(x => x.Split('#')[0].Trim()), StringComparer.OrdinalIgnoreCase);
        string[] missing = domains.Where(d => !existing.Contains(d)).ToArray();
        if (missing.Length == 0) return "Домены Meta / Quest уже добавлены.";
        string backup = Files.Replace(path, Encoding.UTF8.GetBytes(original.TrimEnd() + "\r\n# Meta / Quest PC\r\n" + string.Join("\r\n", missing) + "\r\n"));
        return "Добавлены домены Meta / Quest. Перезапусти Zapret. Копия: " + backup + ". Это список обработки трафика, не гарантия работы входа или загрузок.";
    }
}
